import React, { useState } from 'react';

interface InputAreaProps {
  onSend: (text: string, mode: 'action' | 'investigation' | 'debug' | 'image_gen') => void;
  isProcessing: boolean;
  isInvestigationMode: boolean;
  onToggleMode: () => void;
}

