    if (isProcessing) return;
    onSend("", 'image_gen');
  };

  return (
    <div className="absolute bottom-0 left-0 right-0 bg-gradient-to-t from-stone-950 via-stone-950 to-transparent pb-8 pt-20 px-4 md:px-0 z-10 pointer-events-none">
