              </div>

              <div className="group">
                <label className="block text-amber-900 text-[10px] uppercase tracking-widest mb-2">Crise Ativa (O Gancho)</label>
                <input
                  type="text"
                  value={formData.activeCrisis}
                  onChange={e => setFormData({ ...formData, activeCrisis: e.target.value })}
                  className="w-full bg-transparent border-b border-stone-800 py-2 text-sm text-red-400 focus:border-red-900 focus:outline-none transition-colors placeholder-stone-800"
                  placeholder="Ex: O Sol está morrendo..."
                />
              </div>
            </div>
          )}

          {step === 2 && (
            <div className="space-y-6 animate-fade-in">
              <div className="group">
                 <label className="block text-amber-900 text-[10px] uppercase tracking-widest mb-2">Sistema de Magia / Tecnologia</label>
                 <textarea
                  value={formData.magicSystem}
