export const useLibrary = () => {
  const [universes, setUniverses] = useState<UniverseTemplate[]>([]);
  const [characters, setCharacters] = useState<CharacterTemplate[]>([]);

  // Save Helpers
  const saveUniversesToStorage = (list: UniverseTemplate[]) => {
    localStorage.setItem('cronos_universes', JSON.stringify(list));
    setUniverses(list);
  };

  const saveCharactersToStorage = (list: CharacterTemplate[]) => {
    localStorage.setItem('cronos_characters', JSON.stringify(list));
    setCharacters(list);
  };

  // Load from LocalStorage on mount (or seed defaults)
  useEffect(() => {
    const savedUniverses = localStorage.getItem('cronos_universes');
    const savedCharacters = localStorage.getItem('cronos_characters');

    if (savedUniverses) {
      setUniverses(JSON.parse(savedUniverses));
    } else {
      saveUniversesToStorage(DEFAULT_UNIVERSES);
    }

    if (savedCharacters) {
      setCharacters(JSON.parse(savedCharacters));
    } else {
      saveCharactersToStorage(DEFAULT_CHARACTERS);
    }
  }, []);

  // Actions
  const addUniverse = (template: Omit<UniverseTemplate, 'id' | 'createdAt'>) => {
    const newUni: UniverseTemplate = {
      ...template,
      id: crypto.randomUUID(),
      createdAt: Date.now()
    };
    saveUniversesToStorage([...universes, newUni]);
  };

  /**
   * EVOLVE UNIVERSE: 
   * Updates the Universe definition with new truths, history, legends AND NEW WORLDS.
   */
  const evolveUniverse = (universeId: string, updates: { 
    newEvents?: string[], 
    newTruths?: string[], 
    champion?: { name: string, feat: string },
    newWorld?: { name: string, description: string }
  }) => {
    const updatedList = universes.map(u => {
      if (u.id !== universeId) return u;

      const newTimeline: TimelineEvent[] = updates.newEvents 
        ? updates.newEvents.map(e => ({ year: 'Presente', event: e, era: 'Era do Jogador' })) 
        : [];

      const newChampion = updates.champion 
        ? [{ characterName: updates.champion.name, feat: updates.champion.feat, date: new Date().toISOString(), status: 'Legend' as const }] 
        : [];

      // Add new world if it doesn't exist yet
      let updatedWorlds = u.worlds || [];
      if (updates.newWorld && !updatedWorlds.some(w => w.name.toLowerCase() === updates.newWorld!.name.toLowerCase())) {
          updatedWorlds = [...updatedWorlds, updates.newWorld];
      }

      return {
        ...u,
        knownTruths: [...(u.knownTruths || []), ...(updates.newTruths || [])], 
        chronicles: [...(u.chronicles || []), ...newTimeline], 
        champions: [...(u.champions || []), ...newChampion],
        worlds: updatedWorlds
      };
    });

    saveUniversesToStorage(updatedList);
  };

  const deleteUniverse = (id: string) => {
    saveUniversesToStorage(universes.filter(u => u.id !== id));
  };

  const addCharacter = (template: Omit<CharacterTemplate, 'id' | 'createdAt'>) => {
    const newChar: CharacterTemplate = {
      ...template,
      id: crypto.randomUUID(),
      createdAt: Date.now()
    };
    saveCharactersToStorage([...characters, newChar]);
  };

  const deleteCharacter = (id: string) => {
    saveCharactersToStorage(characters.filter(c => c.id !== id));
  };

  const restoreDefaults = () => {
    saveUniversesToStorage(DEFAULT_UNIVERSES);
    saveCharactersToStorage(DEFAULT_CHARACTERS);
  };

  return {
    universes,
    characters,
    addUniverse,
    evolveUniverse,
    deleteUniverse,
    addCharacter,
    deleteCharacter,
    restoreDefaults
  };
};

import React, { useState, useEffect } from 'react';
import { UniverseTemplate, CharacterTemplate } from '../../types';

interface AdventureLauncherProps {
  universes: UniverseTemplate[];
  characters: CharacterTemplate[];
  onStartAdventure: (universe: UniverseTemplate, character: CharacterTemplate, planetLocation: string) => void;
  onCancel: () => void;
}

const AdventureLauncher: React.FC<AdventureLauncherProps> = ({ universes, characters, onStartAdventure, onCancel }) => {
  const [selectedUniverse, setSelectedUniverse] = useState<string | null>(null);
  const [selectedCharacter, setSelectedCharacter] = useState<string | null>(null);

  // World Selection
  const [worldMode, setWorldMode] = useState<'EXISTING' | 'NEW'>('EXISTING');
  const [selectedWorldName, setSelectedWorldName] = useState<string>('');
  const [newWorldName, setNewWorldName] = useState('');

  const getUniverse = (id: string) => universes.find(u => u.id === id);
  const getCharacter = (id: string) => characters.find(c => c.id === id);

  const activeUniverse = selectedUniverse ? getUniverse(selectedUniverse) : null;

  // Reset world selection when universe changes
  useEffect(() => {
    setWorldMode('EXISTING');
    setSelectedWorldName('');
    setNewWorldName('');
  }, [selectedUniverse]);

  const handleStart = () => {
    const finalLocation = worldMode === 'EXISTING' ? selectedWorldName : newWorldName;

    if (selectedUniverse && selectedCharacter && finalLocation.trim()) {
      const u = getUniverse(selectedUniverse);
      const c = getCharacter(selectedCharacter);
      if (u && c) onStartAdventure(u, c, finalLocation);
    }
  };

  return (
    <div className="flex-1 flex flex-col p-6 bg-stone-950 animate-fade-in overflow-y-auto pb-24">
      <div className="max-w-6xl w-full mx-auto space-y-8">

        <header className="flex flex-col md:flex-row items-start md:items-end justify-between border-b border-stone-900 pb-4 gap-4">
            <div>
                <h2 className="text-4xl font-serif text-stone-200 tracking-tight">Portais Dimensionais</h2>
                <p className="text-stone-600 text-xs uppercase tracking-widest mt-2">Escolha o Universo e o Mundo onde a trama ocorrerá</p>
            </div>
        </header>

        <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">

            {/* COLUMN 1: UNIVERSE SELECTION (Width 4) */}
            <div className="lg:col-span-4 space-y-4 flex flex-col h-full">
                <h3 className="text-amber-900 text-[10px] uppercase tracking-widest border-b border-stone-900 pb-2">1. Selecione o Universo</h3>
                <div className="space-y-3 flex-1 overflow-y-auto max-h-[500px] custom-scrollbar pr-2">
                    {universes.length === 0 && (
                        <div className="p-8 border border-dashed border-stone-800 text-center text-stone-600 text-xs italic">
                            Nenhum universo encontrado.<br/>Crie um na biblioteca.
                        </div>
                    )}
                    {universes.map(u => (
                        <button
                            key={u.id}
                            onClick={() => setSelectedUniverse(u.id)}
                            className={`w-full text-left p-4 rounded-sm border transition-all ${
                                selectedUniverse === u.id 
                                ? 'bg-amber-900/20 border-amber-700' 
                                : 'bg-stone-900/30 border-stone-800 hover:bg-stone-900'
                            }`}
                        >
                            <div className="flex justify-between mb-1">
                                <span className={`font-serif text-lg ${selectedUniverse === u.id ? 'text-amber-500' : 'text-stone-300'}`}>
                                    {u.name}
                                </span>
                            </div>
                            <p className="text-stone-500 text-xs line-clamp-2">{u.description}</p>

                            {/* Universe Stats Badges */}
                            <div className="mt-3 flex gap-2 flex-wrap">
                                {(u.champions && u.champions.length > 0) && (
                                    <span className="text-[9px] bg-stone-950 text-amber-600 border border-stone-800 px-1.5 py-0.5 rounded flex items-center gap-1">
                                        ★ {u.champions.length} Lendas
                                    </span>
                                )}
                                {(u.worlds && u.worlds.length > 0) && (
                                    <span className="text-[9px] bg-stone-950 text-emerald-600 border border-stone-800 px-1.5 py-0.5 rounded flex items-center gap-1">
                                        ● {u.worlds.length} Mundos
                                    </span>
                                )}
                            </div>
                        </button>
                    ))}
                </div>
            </div>

            {/* COLUMN 2: WORLD SELECTION (Width 5) */}
            <div className="lg:col-span-5 space-y-6 bg-stone-900/10 p-6 border border-stone-900/50 rounded-sm">
                 {activeUniverse ? (
                     <div className="space-y-6 animate-fade-in">
                        <div>
                            <h3 className="text-2xl font-serif text-stone-300">{activeUniverse.name}</h3>
                            <span className="text-[10px] text-stone-500 uppercase tracking-widest">{activeUniverse.cosmology || 'Cosmologia Desconhecida'}</span>
                            <p className="mt-4 text-stone-400 text-sm leading-relaxed italic border-l-2 border-stone-800 pl-4">{activeUniverse.description}</p>
                        </div>

                        <div className="h-px bg-stone-800 w-full"></div>

                        {/* World Picker */}
                        <div className="space-y-4">
                             <h3 className="text-amber-900 text-[10px] uppercase tracking-widest">2. Selecione o Mundo / Local</h3>

                             <div className="flex gap-2 bg-stone-950 p-1 rounded border border-stone-800">
                                <button 
                                    onClick={() => setWorldMode('EXISTING')}
                                    className={`flex-1 py-2 text-[10px] uppercase tracking-wider rounded-sm transition-colors ${worldMode === 'EXISTING' ? 'bg-stone-800 text-amber-500' : 'text-stone-600 hover:text-stone-400'}`}
                                >
                                    Mundos Conhecidos
                                </button>
                                <button 
                                    onClick={() => setWorldMode('NEW')}
                                    className={`flex-1 py-2 text-[10px] uppercase tracking-wider rounded-sm transition-colors ${worldMode === 'NEW' ? 'bg-stone-800 text-emerald-500' : 'text-stone-600 hover:text-stone-400'}`}
                                >
                                    Explorar Novo
                                </button>
                             </div>

                             {worldMode === 'EXISTING' ? (
                                <div className="space-y-2">
                                    {activeUniverse.worlds && activeUniverse.worlds.length > 0 ? (
                                        <div className="grid gap-2">
                                            {activeUniverse.worlds.map((w, idx) => (
                                                <button
                                                    key={idx}
                                                    onClick={() => setSelectedWorldName(w.name)}
                                                    className={`text-left p-3 border rounded-sm transition-colors ${selectedWorldName === w.name ? 'border-amber-600 bg-amber-900/10' : 'border-stone-800 bg-stone-900/50 hover:bg-stone-900'}`}
                                                >
                                                    <div className="text-sm font-serif text-stone-300">{w.name}</div>
                                                    <div className="text-[10px] text-stone-500 truncate">{w.description}</div>
                                                </button>
                                            ))}
                                        </div>
                                    ) : (
                                        <div className="text-center py-6 text-stone-600 text-xs italic">
                                            Nenhum mundo registrado neste universo ainda.
                                            <br/>
                                            <button onClick={() => setWorldMode('NEW')} className="text-amber-600 underline mt-2 hover:text-amber-500">Criar o primeiro</button>
                                        </div>
                                    )}
                                </div>
                             ) : (
                                <div className="space-y-2 animate-fade-in">
                                    <input 
                                        type="text"
                                        value={newWorldName}
                                        onChange={(e) => setNewWorldName(e.target.value)}
                                        placeholder="Nome do Novo Mundo (Ex: Terra-616, Nárnia)..."
                                        className="w-full bg-stone-950 border-b border-stone-700 py-3 text-stone-200 focus:border-emerald-600 focus:outline-none transition-colors"
                                    />
                                    <p className="text-[10px] text-stone-500">
                                        Este novo local será registrado permanentemente no Universo {activeUniverse.name} ao iniciar a aventura.
                                    </p>
                                </div>
                             )}
                        </div>

                     </div>
                 ) : (
                     <div className="h-full flex items-center justify-center text-stone-700 text-sm italic">
                         Selecione um universo à esquerda para ver seus mundos.
                     </div>
