                <h3 className="text-amber-900 text-[10px] uppercase tracking-widest border-b border-stone-900 pb-2">3. Selecione o Receptáculo</h3>
                <div className="space-y-3 flex-1 overflow-y-auto max-h-[500px] custom-scrollbar">
                    {characters.map(c => (
                        <button
                            key={c.id}
                            onClick={() => setSelectedCharacter(c.id)}
                            className={`w-full text-left p-3 rounded-sm border transition-all ${
                                selectedCharacter === c.id 
                                ? 'bg-amber-900/20 border-amber-700' 
                                : 'bg-stone-900/30 border-stone-800 hover:bg-stone-900'
                            }`}
                        >
                            <div className="flex justify-between mb-1">
                                <span className={`font-serif text-sm ${selectedCharacter === c.id ? 'text-amber-500' : 'text-stone-300'}`}>
                                    {c.name}
                                </span>
                            </div>
                            <span className="text-[9px] uppercase tracking-wider text-stone-600 border border-stone-800 px-1 rounded">
                                {c.archetype}
                            </span>
                        </button>
                    ))}
                </div>
            </div>
        </div>

        {/* START BUTTON */}
        <div className="pt-8 border-t border-stone-900 text-center">
            <button
                onClick={handleStart}
                disabled={!selectedUniverse || !selectedCharacter || (!selectedWorldName && !newWorldName)}
                className="px-16 py-5 bg-stone-100 text-stone-950 font-serif tracking-widest uppercase hover:bg-amber-500 transition-colors disabled:opacity-20 disabled:cursor-not-allowed shadow-[0_0_20px_rgba(255,255,255,0.1)] text-lg"
            >
                Materializar
            </button>
        </div>

      </div>
    </div>
  );
};

export default AdventureLauncher;

import React, { useState, useEffect } from 'react';
import ApiKeyModal from './components/ApiKeyModal';
import WorldStatePanel from './components/WorldStatePanel';
import GameHeader from './components/GameHeader';
import GameLog from './components/GameLog';
import InputArea from './components/InputArea';
// EntryScreen import removed

// Navigation & Creators
import BottomNav, { NavTab } from './components/BottomNav';
import { UniverseList, CharacterList } from './components/library/LibraryViews';
import UniverseCreator from './components/creators/UniverseCreator';
import CharacterCreator from './components/creators/CharacterCreator';
import AdventureLauncher from './components/creators/AdventureLauncher';

import { useGameEngine } from './hooks/useGameEngine';
import { usePersistence } from './hooks/usePersistence';
import { useLibrary } from './hooks/useLibrary';
import { UniverseTemplate, CharacterTemplate } from './types';
import { checkBackendHealth } from './services/ragService';

// Types for Navigation
type ViewState = 'ADVENTURE_LAUNCHER' | 'UNIVERSE_LIST' | 'UNIVERSE_CREATOR' | 'CHARACTER_LIST' | 'CHARACTER_CREATOR' | 'SETTINGS' | 'GAME';

function App() {
  const [hasApiKey, setHasApiKey] = useState(false);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isInvestigationMode, setIsInvestigationMode] = useState(false);

  // Navigation State
  const [currentView, setCurrentView] = useState<ViewState>('ADVENTURE_LAUNCHER');

  // Settings State
  const [backendStatus, setBackendStatus] = useState<'checking' | 'online' | 'offline'>('checking');

  // Library Hook (Now provides evolveUniverse)
  const { universes, characters, addUniverse, addCharacter, restoreDefaults, evolveUniverse } = useLibrary();

  // Hooks (Pass evolveUniverse to engine)
  const { gameState, isProcessing, startGame, performAction, resetGame, restoreGame } = useGameEngine(evolveUniverse);
  const { saveGame, parseSaveFile } = usePersistence();

  // Auto-open sidebar when game starts
  useEffect(() => {
    if (gameState && currentView === 'GAME') {
      setIsSidebarOpen(true);
    }
  }, [gameState, currentView]);

  // Check Backend Health when entering Settings
  useEffect(() => {
    if (currentView === 'SETTINGS') {
      setBackendStatus('checking');
      checkBackendHealth().then(isOnline => {
        setBackendStatus(isOnline ? 'online' : 'offline');
      });
    }
  }, [currentView]);

  const handleStartAdventure = (u: UniverseTemplate, c: CharacterTemplate, planetLocation: string) => {

    // Check if this is a NEW world for this universe and register it
    const isNewWorld = !u.worlds?.some(w => w.name.toLowerCase() === planetLocation.toLowerCase());
    if (isNewWorld) {
        evolveUniverse(u.id, {
            newWorld: { 
                name: planetLocation, 
                description: "Mundo descoberto recentemente." 
            }
        });
    }

    // We construct a DEEP context including physics, laws, history AND persistent legends
    const physicsBlock = u.physics && u.physics.length > 0 ? `LEIS DA REALIDADE (Imutáveis):\n${u.physics.map(p=>`- ${p}`).join('\n')}` : '';
    const truthsBlock = u.knownTruths && u.knownTruths.length > 0 ? `VERDADES DESCOBERTAS (Conhecimento Acumulado):\n${u.knownTruths.map(t=>`- ${t}`).join('\n')}` : '';

    const timelineBlock = u.chronicles && u.chronicles.length > 0 ? `CRONOLOGIA CANÔNICA DO UNIVERSO:\n${u.chronicles.map(t=>`[${t.year}] ${t.event}`).join('\n')}` : '';

    const legendsBlock = u.champions && u.champions.length > 0 ? `LENDAS E HERÓIS PASSADOS:\n${u.champions.map(ch => `- ${ch.characterName}: ${ch.feat} (${ch.status})`).join('\n')}` : '';

    const magicBlock = u.magicSystem ? `SISTEMA DE MAGIA/TECNOLOGIA: ${u.magicSystem}` : '';

    const fullSettingContext = `
      UNIVERSE CONTAINER: ${u.name} (${u.genre})
      DESCRIÇÃO DO UNIVERSO: ${u.description}
      COSMOLOGIA: ${u.cosmology || 'Desconhecida'}

      ${physicsBlock}

      ${magicBlock}

      ${truthsBlock}

      ${timelineBlock}

      ${legendsBlock}

      ---
      STARTING WORLD / LOCAL DA TRAMA: ${planetLocation}
      ---

      CHARACTER: ${c.name} (${c.archetype}). ${c.description}
    `;

    // Updated signature: pass universe ID and Name for Persistent Memory
    startGame(c.name, fullSettingContext, u.id, u.name);
    setCurrentView('GAME');
  };

  const handleLoadGame = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    try {
      const loadedState = await parseSaveFile(file);
      restoreGame(loadedState);
      setCurrentView('GAME');
    } catch (err) {
      console.error(err);
      alert("Arquivo de save inválido ou corrompido.");
    }
  };

  const handleExitToHub = () => {
    if (window.confirm("Sair para o Menu Principal? O progresso não salvo será perdido.")) {
      resetGame(); // Clears current session
      setCurrentView('ADVENTURE_LAUNCHER');
    }
  };

  // Determine active tab for BottomNav based on currentView
  const getActiveTab = (): NavTab => {
    if (currentView === 'UNIVERSE_LIST' || currentView === 'UNIVERSE_CREATOR') return 'UNIVERSES';
    if (currentView === 'CHARACTER_LIST' || currentView === 'CHARACTER_CREATOR') return 'CHARACTERS';
    if (currentView === 'SETTINGS') return 'SETTINGS';
    return 'PLAY';
  };

  const handleTabChange = (tab: NavTab) => {
    switch (tab) {
      case 'PLAY': setCurrentView('ADVENTURE_LAUNCHER'); break;
      case 'UNIVERSES': setCurrentView('UNIVERSE_LIST'); break;
      case 'CHARACTERS': setCurrentView('CHARACTER_LIST'); break;
      case 'SETTINGS': setCurrentView('SETTINGS'); break;
    }
  };

  // --- RENDER LOGIC ---

  if (!hasApiKey) return <ApiKeyModal onKeySelected={() => setHasApiKey(true)} />;

  return (
    <div className="flex h-screen bg-stone-950 text-stone-200 overflow-hidden relative">

      {/* Main Content Area */}
      <div className={`flex-1 flex flex-col min-w-0 relative transition-all duration-300 ${isSidebarOpen && currentView === 'GAME' ? 'mr-0 md:mr-80' : 'mr-0'}`}>

        {/* Header is always visible but changes context */}
        <GameHeader 
          gameState={gameState}
          setupMode={currentView !== 'GAME'}
          isSidebarOpen={isSidebarOpen}
          onToggleSidebar={() => setIsSidebarOpen(!isSidebarOpen)}
          onReset={handleExitToHub} // In Game Mode, this exits to Hub
          onSave={() => saveGame(gameState)}
          onLoad={handleLoadGame}
        />

        {/* View Router */}

        {/* TAB: PLAY */}
        {currentView === 'ADVENTURE_LAUNCHER' && (
          <AdventureLauncher 
            universes={universes}
            characters={characters}
            onStartAdventure={handleStartAdventure}
            onCancel={() => {}} // No cancel action needed on root
          />
        )}

        {/* TAB: UNIVERSES */}
        {currentView === 'UNIVERSE_LIST' && (
          <UniverseList onCreate={() => setCurrentView('UNIVERSE_CREATOR')} />
        )}
        {currentView === 'UNIVERSE_CREATOR' && (
          <UniverseCreator 
            onSave={(t) => { addUniverse(t); setCurrentView('UNIVERSE_LIST'); }} 
            onCancel={() => setCurrentView('UNIVERSE_LIST')} 
          />
        )}

        {/* TAB: CHARACTERS */}
        {currentView === 'CHARACTER_LIST' && (
          <CharacterList onCreate={() => setCurrentView('CHARACTER_CREATOR')} />
        )}
        {currentView === 'CHARACTER_CREATOR' && (
          <CharacterCreator 
            onSave={(t) => { addCharacter(t); setCurrentView('CHARACTER_LIST'); }} 
            onCancel={() => setCurrentView('CHARACTER_LIST')} 
          />
        )}

        {/* TAB: SETTINGS */}
        {currentView === 'SETTINGS' && (
           <div className="flex-1 flex flex-col items-center justify-center text-stone-500 text-sm p-8 animate-fade-in overflow-y-auto">
              <div className="text-center space-y-4 max-w-md w-full pb-20">
                 <h2 className="text-2xl font-serif text-stone-300">Sistema Cronos</h2>
                 <p className="text-xs uppercase tracking-widest border-b border-stone-900 pb-4">Diagnósticos & Configuração</p>

                 <div className="bg-stone-900/30 p-6 rounded border border-stone-800 text-left space-y-6">

                   <div className="border-b border-stone-800 pb-2 mb-2 flex justify-between items-center">
                      <h3 className="text-stone-400 font-serif text-sm uppercase tracking-wider">Topologia de Rede</h3>
                      <span className="text-[9px] text-stone-600 bg-stone-900 px-2 py-0.5 rounded">2 Nós Ativos</span>
                   </div>

                   {/* Google API Status */}
                   <div>
                     <label className="block text-[10px] uppercase text-stone-500 mb-1 flex items-center justify-between">
                        <span>Núcleo Neural (LLM)</span>
                        <span className="text-stone-600">Google Cloud</span>
                     </label>
                     <div className="flex items-center gap-2 text-green-500 text-xs font-mono bg-stone-950/50 p-2 rounded border border-stone-900">
                       <span className="w-2 h-2 bg-green-500 rounded-full animate-pulse"></span>
                       Gemini 2.5 API (Conectado)
                     </div>
                   </div>

                   {/* Backend/RAG Status */}
                   <div>
                     <label className="block text-[10px] uppercase text-stone-500 mb-1 flex items-center justify-between">
                        <span>Orquestrador de Memória</span>
                        <span className="text-stone-600">Servidor RAG (Python)</span>
                     </label>
                     <div className={`flex items-center gap-2 text-xs font-mono bg-stone-950/50 p-2 rounded border border-stone-900 transition-colors duration-300 ${
                       backendStatus === 'online' ? 'text-green-500 border-green-900/30' : backendStatus === 'checking' ? 'text-amber-500' : 'text-red-500 border-red-900/30'
                     }`}>
                       <span className={`w-2 h-2 rounded-full ${
                         backendStatus === 'online' ? 'bg-green-500 animate-pulse' : backendStatus === 'checking' ? 'bg-amber-500 animate-bounce' : 'bg-red-500'
                       }`}></span>
                       {backendStatus === 'checking' ? 'Negociando handshake...' : backendStatus === 'online' ? 'Link Neural Estável' : 'Sinal Perdido (Offline)'}
                     </div>

                     {/* Sub-systems visualization */}
                     <div className="mt-2 pl-3 border-l-2 border-stone-800 space-y-1">
                        <div className="flex items-center justify-between text-[10px] py-1">
                           <span className="text-stone-400">Vector Store (ChromaDB)</span>
                           <span className={backendStatus === 'online' ? "text-green-600" : "text-stone-700"}>{backendStatus === 'online' ? '●' : '○'}</span>
                        </div>
                        <div className="flex items-center justify-between text-[10px] py-1">
                           <span className="text-stone-400">Knowledge Graph (Neo4j)</span>
                           <span className={backendStatus === 'online' ? "text-green-600" : "text-stone-700"}>{backendStatus === 'online' ? '●' : '○'}</span>
                        </div>
                        <div className="flex items-center justify-between text-[10px] py-1">
                           <span className="text-stone-400">Event Logs (SQLite)</span>
                           <span className={backendStatus === 'online' ? "text-green-600" : "text-stone-700"}>{backendStatus === 'online' ? '●' : '○'}</span>
                        </div>
                     </div>

                     {backendStatus === 'offline' && (
                       <p className="text-[10px] text-red-900/70 mt-2 italic border-t border-red-900/10 pt-1">
                         A persistência de longo prazo está indisponível. A simulação usará apenas a memória de contexto (RAM).
                       </p>
                     )}
                   </div>

                   <div className="h-px bg-stone-800 w-full my-4"></div>

                   <div>
                     <label className="block text-[10px] uppercase text-stone-600 mb-1">Versão do Cliente</label>
                     <span className="text-stone-400 text-xs font-mono">v1.3.0 (Universe Deep Layer)</span>
                   </div>

                    <div>
                     <label className="block text-[10px] uppercase text-stone-600 mb-1">Manutenção</label>
                     <div className="flex flex-col gap-2">
                        <button onClick={() => { if(confirm('Restaurar universos e personagens de exemplo?')) { restoreDefaults(); alert('Templates restaurados!'); window.location.reload(); } }} className="text-amber-500 hover:text-amber-400 text-xs text-left">
                          Restaurar Templates de Exemplo
                        </button>
                        <button onClick={() => { if(confirm('Limpar todas as bibliotecas e resetar o app?')) { localStorage.clear(); window.location.reload(); } }} className="text-red-500 hover:text-red-400 text-xs text-left">
                          Limpar Dados Locais (Reset Fábrica)
                        </button>
                     </div>
                   </div>
                 </div>
              </div>
           </div>
        )}

        {/* GAME VIEW */}
        {currentView === 'GAME' && (
          <>
            <GameLog 
              history={gameState?.history || []} 
              isProcessing={isProcessing} 
              isInvestigationMode={isInvestigationMode}
            />
            <InputArea 
              onSend={performAction}
              isProcessing={isProcessing}
              isInvestigationMode={isInvestigationMode}
              onToggleMode={() => setIsInvestigationMode(!isInvestigationMode)}
            />
          </>
        )}
      </div>

      {/* Sidebar - Only active in GAME view */}
      {currentView === 'GAME' && (
        <WorldStatePanel 
          gameState={gameState} 
          isOpen={isSidebarOpen} 
          onToggle={() => setIsSidebarOpen(!isSidebarOpen)} 
        />
      )}

      {/* Bottom Navigation - Only active when NOT in game */}
      {currentView !== 'GAME' && (
        <BottomNav activeTab={getActiveTab()} onTabChange={handleTabChange} />
      )}

    </div>
  );
}

export default App;

import React, { useState } from 'react';
import { UniverseTemplate } from '../../types';

interface UniverseCreatorProps {
  onSave: (template: Omit<UniverseTemplate, 'id' | 'createdAt'>) => void;
  onCancel: () => void;
}

const UniverseCreator: React.FC<UniverseCreatorProps> = ({ onSave, onCancel }) => {
  const [formData, setFormData] = useState<Partial<UniverseTemplate>>({
    name: '',
    description: '',
    genre: '',
    physics: [],
    magicSystem: '',
    cosmology: '',
    chronicles: [],
    worlds: []
  });

  const [newLaw, setNewLaw] = useState('');
  const [step, setStep] = useState<1 | 2>(1);

  const addLaw = () => {
    if (newLaw.trim()) {
      setFormData(prev => ({ ...prev, physics: [...(prev.physics || []), newLaw.trim()] }));
      setNewLaw('');
    }
  };

  const removeLaw = (index: number) => {
    setFormData(prev => ({ ...prev, physics: prev.physics?.filter((_, i) => i !== index) }));
  };

  const handleSave = () => {
    if (!formData.name || !formData.genre) return;
    onSave(formData as Omit<UniverseTemplate, 'id' | 'createdAt'>);
  };

  return (
    <div className="flex-1 flex flex-col items-center justify-center p-6 bg-stone-950 animate-fade-in pb-24 overflow-y-auto">
      <div className="max-w-3xl w-full space-y-8">
        <div className="text-center">
          <h2 className="text-3xl font-serif text-stone-200 tracking-tight">Arquitetura de Mundo</h2>
          <p className="text-stone-600 text-xs uppercase tracking-widest mt-2">
            {step === 1 ? 'Fundação & Atmosfera' : 'Leis & Metafísica'}
          </p>
        </div>

        <div className="bg-stone-900/20 p-8 border border-stone-800 rounded-sm space-y-6">

          {step === 1 && (
            <div className="space-y-6 animate-fade-in">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="group">
                  <label className="block text-amber-900 text-[10px] uppercase tracking-widest mb-2">Nome do Universo *</label>
                  <input
                    type="text"
                    value={formData.name}
                    onChange={e => setFormData({ ...formData, name: e.target.value })}
                    className="w-full bg-transparent border-b border-stone-800 py-2 text-lg text-stone-300 focus:border-amber-700 focus:outline-none transition-colors font-serif"
                    placeholder="Ex: Neo-Veridia"
                  />
                </div>
                <div className="group">
                  <label className="block text-amber-900 text-[10px] uppercase tracking-widest mb-2">Gênero *</label>
                  <input
                    type="text"
                    value={formData.genre}
                    onChange={e => setFormData({ ...formData, genre: e.target.value })}
                    className="w-full bg-transparent border-b border-stone-800 py-2 text-lg text-stone-300 focus:border-amber-700 focus:outline-none transition-colors font-serif"
                    placeholder="Ex: Dark Fantasy"
                  />
                </div>
              </div>

              <div className="group">
                <label className="block text-amber-900 text-[10px] uppercase tracking-widest mb-2">Descrição Atmosférica</label>
                <textarea
                  value={formData.description}
                  onChange={e => setFormData({ ...formData, description: e.target.value })}
                  className="w-full bg-stone-950/50 border border-stone-800 p-4 text-stone-300 focus:border-amber-700 focus:outline-none rounded-sm h-32 resize-none text-sm leading-relaxed"
                  placeholder="Descreva o cheiro, a luz e a sensação deste mundo..."
                />
              </div>

              <div className="group">
                <label className="block text-amber-900 text-[10px] uppercase tracking-widest mb-2">Cosmologia / Estrutura</label>
                <input
                  type="text"
                  value={formData.cosmology}
                  onChange={e => setFormData({ ...formData, cosmology: e.target.value })}
                  className="w-full bg-transparent border-b border-stone-800 py-2 text-sm text-stone-400 focus:border-amber-900 focus:outline-none transition-colors placeholder-stone-800"
                  placeholder="Ex: Sistema Solar Binário, 9 Reinos, Terra Plana Infinita..."
                />
              </div>
            </div>
          )}

          {step === 2 && (
            <div className="space-y-6 animate-fade-in">
              <div className="group">
                 <label className="block text-amber-900 text-[10px] uppercase tracking-widest mb-2">Sistema de Magia / Tecnologia</label>
                 <textarea
                  value={formData.magicSystem}
                  onChange={e => setFormData({ ...formData, magicSystem: e.target.value })}
                  className="w-full bg-stone-950/50 border border-stone-800 p-4 text-cyan-200/80 focus:border-cyan-900 focus:outline-none rounded-sm h-24 resize-none text-sm leading-relaxed"
                  placeholder="Como o impossível acontece aqui? Ex: Nanomáquinas no sangue, pactos demoníacos..."
                />
              </div>

              <div className="group">
                <label className="block text-amber-900 text-[10px] uppercase tracking-widest mb-2">Leis da Realidade (Física & Regras)</label>
                <div className="flex gap-2 mb-4">
                  <input
                    type="text"
                    value={newLaw}
                    onChange={e => setNewLaw(e.target.value)}
                    onKeyDown={e => e.key === 'Enter' && addLaw()}
                    className="flex-1 bg-stone-950/50 border border-stone-800 p-2 text-sm text-stone-300 focus:border-amber-700 focus:outline-none"
                    placeholder="Ex: A gravidade é metade da Terra..."
                  />
                  <button onClick={addLaw} className="px-4 bg-stone-800 text-stone-400 hover:text-amber-500 border border-stone-700">+</button>
                </div>
                <ul className="space-y-2 max-h-40 overflow-y-auto custom-scrollbar">
                  {formData.physics?.map((law, idx) => (
                    <li key={idx} className="flex justify-between items-center bg-stone-900/40 p-2 border-l-2 border-amber-900/50 text-xs text-stone-400">
                      <span>{law}</span>
                      <button onClick={() => removeLaw(idx)} className="text-stone-600 hover:text-red-500 px-2">×</button>
                    </li>
                  ))}
                  {(!formData.physics || formData.physics.length === 0) && (
                    <li className="text-stone-700 italic text-xs">Nenhuma lei especial definida.</li>
                  )}
                </ul>
              </div>
            </div>
          )}

          {/* Navigation Buttons */}
          <div className="flex gap-4 pt-4 border-t border-stone-800/50">
            {step === 2 ? (
               <button
                onClick={() => setStep(1)}
                className="px-6 py-3 border border-stone-800 text-stone-500 hover:text-stone-300 hover:bg-stone-900 transition-colors text-xs uppercase tracking-widest"
              >
                Voltar
              </button>
            ) : (
              <button
                onClick={onCancel}
                className="flex-1 py-3 border border-stone-800 text-stone-500 hover:text-stone-300 hover:bg-stone-900 transition-colors text-xs uppercase tracking-widest"
              >
                Cancelar
              </button>
            )}

            {step === 1 ? (
              <button
                onClick={() => setStep(2)}
                disabled={!formData.name || !formData.genre}
                className="flex-1 py-3 bg-stone-900 border border-stone-800 text-amber-500 hover:bg-amber-900/10 hover:border-amber-900 transition-colors text-xs uppercase tracking-widest disabled:opacity-30"
              >
                Próximo: Leis
              </button>
            ) : (
              <button
                onClick={handleSave}
                className="flex-1 py-3 bg-amber-900/20 border border-amber-900/30 text-amber-500 hover:bg-amber-900/40 hover:border-amber-700 transition-colors text-xs uppercase tracking-widest"
              >
                Materializar Universo
              </button>
            )}
          </div>

        </div>
      </div>
    </div>
  );
};

export default UniverseCreator;

