  type: 'character' | 'location' | 'lore';
  description: string;
  status?: string; // e.g., "Ally", "Enemy", "Visited", "Unknown"
}

export interface QuestEntry {
  id: string;
  title: string;
  description: string;
  status: 'active' | 'completed' | 'failed';
}

export interface NPCEntity {
  id: string; 
  name: string; 
  descriptor: string; 
  isNameKnown: boolean; 
  location: string;
  action: string; 
  lastThought: string; 
  status: string; 
}

export interface GraphEdge {
  subject: string;
  relation: string;
  object: string;
  properties?: Record<string, any>;
}

