}

export interface GameState {
  universeId: string;

  player: {
    name: string;
    description: string;
    inventory: string[];
    status: string;
    location: string;
    stats: PlayerStats; 
  };
  world: {
    time: string;
    weather: string;
    activeEvents: string[];
    npcs: NPCEntity[];
  };
