import { GameState, SimulationResponse, NarrativeResponse, WorldUpdate, NPCBehaviorResponse, CharacterTemplate } from "../types";
import { synthesizeNarrative, initializeGameSession } from "./agents/narrator";
import { runNPCBehaviorEngine } from "./agents/npc";
import { runWorldSimulation } from "./agents/world";
import { investigateScene, summarizeMemory, debugSimulation } from "./agents/system";
import { resolveDialogueTags } from "./agents/dialogue";
import { ingestUnifiedMemory, UnifiedIngestPayload } from "./ragService";

// Re-export specific agent functions
export { investigateScene, summarizeMemory, debugSimulation };

// --- PHASE 1: NARRATIVE (Fast, User Facing) ---
export const generateStory = async (
  action: string, 
  currentState: GameState
): Promise<NarrativeResponse> => {
  // 1. Narrator generates story with placeholders [[DIALOGUE:...]]
  // Pass the Universe ID for RAG Context Retrieval
  const rawResponse = await synthesizeNarrative(action, currentState);

  // 2. Dialogue Agent resolves placeholders in parallel
  const finalNarrativeText = await resolveDialogueTags(rawResponse.narrative, currentState);

  // 3. RETURN immediately for UI rendering.
  return {
    ...rawResponse,
    narrative: finalNarrativeText
  };
};

// --- PHASE 2: STATE SYNCHRONIZATION (Background) ---
export const synchronizeState = async (
  action: string,
  narrative: string,
  currentState: GameState,
  narrativeResponse?: NarrativeResponse // Passed to get graph data
): Promise<{ world: WorldUpdate, npcs: NPCBehaviorResponse }> => {

  // Parallel execution of state updaters
  const [worldRes, npcRes] = await Promise.all([
    runWorldSimulation(action, narrative, currentState),
    runNPCBehaviorEngine(currentState, action, narrative)
  ]);

  // --- TRIPLE STORE INGESTION ---
  if (narrativeResponse) {

      // Calculate snapshot of inventory for logs
      let currentInventory = [...currentState.player.inventory];
      if (worldRes.inventoryUpdates?.added) {
        currentInventory.push(...worldRes.inventoryUpdates.added);
      }
      if (worldRes.inventoryUpdates?.removed) {
        currentInventory = currentInventory.filter(item => !worldRes.inventoryUpdates?.removed?.includes(item));
      }

      const payload: UnifiedIngestPayload = {
          universeId: currentState.universeId,
          turnId: currentState.history.length + 1,
          timestamp: currentState.world.time, 

          // 1. Vector (Chroma)
          vectorData: {
              text: `[ACTION]: ${action}\n[RESULT]: ${narrative}`,
              type: 'turn',
              location: worldRes.newLocation
          },

          // 2. SQL (Logs)
          sqlData: {
              playerStatus: worldRes.playerStatus,
              inventory: currentInventory,
              worldState: {
                  location: worldRes.newLocation,
                  time: worldRes.timePassed,
                  weather: worldRes.currentWeather
              }
          },

          // 3. Graph (Neo4j)
          graphData: narrativeResponse.graphUpdates || []
      };

      // Fire and forget
      ingestUnifiedMemory(payload);

      // Handle specific Lore Canonical Events
      if (narrativeResponse.canonicalEvents && narrativeResponse.canonicalEvents.length > 0) {
          narrativeResponse.canonicalEvents.forEach(event => {
             const lorePayload: UnifiedIngestPayload = {
                 ...payload,
                 vectorData: { ...payload.vectorData, text: event, type: 'lore' },
                 graphData: [] 
             };
             ingestUnifiedMemory(lorePayload);
          });
      }
  }

  return {
    world: worldRes,
    npcs: npcRes
  };
};

export const initializeGame = async (character: CharacterTemplate, setting: string, universeId: string, universeName: string): Promise<SimulationResponse> => {
  // 1. Narrator creates initial state, pulling RAG context from the Universe ID
  // We pass the full character object to give the narrator the "Soul" context
  const rawResponse = await initializeGameSession(character, setting, universeId, universeName);

  // 2. Resolve any initial dialogues (though less likely in intro, it supports it)
  const mockState: GameState = {
    universeId: universeId,
    player: { 
        sourceId: character.id,
        name: character.name, 
        description: character.description, 
        inventory: [], 
        status: "", 
        location: "",
        stats: {
            strength: 10,
            agility: 10,
            intelligence: 10,
            spirit: 10,
            health: 100,
            maxHealth: 100
        }
    },
    world: { time: "", weather: "", activeEvents: [], npcs: rawResponse.npcSimulation || [] },
    knowledgeBase: { characters: [], locations: [], lore: [], quests: [] },
    summary: "",
    history: []
  };

  const finalNarrativeText = await resolveDialogueTags(rawResponse.narrative, mockState);

  // Ingest initial LORE if generated
  const payload: UnifiedIngestPayload = {
      universeId: universeId,
      turnId: 0,
      timestamp: rawResponse.initialTime || "Start",
      vectorData: {
          text: finalNarrativeText,
          type: 'intro',
          location: "Start"
      },
      sqlData: {
          playerStatus: "Healthy",
          inventory: [],
          worldState: {}
      },
      graphData: rawResponse.graphUpdates || []
  };
  ingestUnifiedMemory(payload);

  return {
    ...rawResponse,
    narrative: finalNarrativeText
  };
};

import { GameState, NarrativeResponse, SimulationResponse, CharacterTemplate } from "../../types";
import { NarrativeSchema, InitSchema } from "../ai/schemas";
import { NARRATOR_INSTRUCTION } from "../ai/prompts";
import { generateContentWithRetry, NARRATOR_MODEL, parseAIResponse } from "../ai/client";
import { getSimulationHistory, getKnowledgeContext } from "../../utils/contextBuilder";
import { retrieveContext } from "../ragService";

// The Narrator is now the FIRST step (The Leader).
// It decides the outcome and writes the story immediately.
export const synthesizeNarrative = async (
  action: string,
  currentState: GameState
): Promise<NarrativeResponse> => {

  // 1. RAG RETRIEVAL (Tenta buscar memórias no servidor Python)
  // Buscamos baseados na ação, localização E HISTÓRIA DO UNIVERSO
  // A query inclui o UniverseID para que o RAG possa (se configurado) filtrar ou priorizar
  const ragQuery = `Action: ${action} | Location: ${currentState.player.location} | Universe: ${currentState.universeId}`;

  const longTermMemories = await retrieveContext(ragQuery);

  const formattedMemories = longTermMemories.length > 0 
    ? `[MEMÓRIAS E LENDAS RECUPERADAS (RAG)]:\n${longTermMemories.map(m => `- ${m}`).join('\n')}`
    : "";

  // 2. Filtra NPCs locais
  const presentNPCs = currentState.world.npcs
    .filter(npc => npc.location === currentState.player.location)
    .map(npc => `- ${npc.isNameKnown ? npc.name : npc.descriptor} (Ação: ${npc.action}, Status: ${npc.status})`)
    .join("\n");

  const context = `
  [HISTÓRICO RECENTE]:
  ${getSimulationHistory(currentState.history)}

  ${formattedMemories}

  [CONTEXTO DE CONHECIMENTO (Códex)]:
  ${getKnowledgeContext(currentState.knowledgeBase)}

  [ESTADO ATUAL DO JOGADOR]:
  Local: ${currentState.player.location}
  Status: ${currentState.player.status}
  Inventário: ${currentState.player.inventory.join(", ")}
  Tempo: ${currentState.world.time}

  [PESSOAS PRESENTES NESTE LOCAL (${currentState.player.location})]:
  ${presentNPCs || "Ninguém visível."}
  `;

  const prompt = `
  AÇÃO DO JOGADOR: "${action}"

  TAREFA DE ESCRITA:
  1. Atue como Mestre de Jogo. Decida o resultado lógico da ação.
  2. Use as [MEMÓRIAS E LENDAS RECUPERADAS] para manter a consistência histórica do universo. Se o jogador encontrar uma estátua descrita no RAG, descreva-a.
  3. Escreva a resposta narrativa em 2ª pessoa usando as tags [[DIALOGUE:...]] para falas.
  4. Se ocorrer algo EPICO que muda a história do mundo, adicione ao campo 'canonicalEvents'.
  `;

  const response = await generateContentWithRetry(NARRATOR_MODEL, {
    contents: context + "\n" + prompt,
    config: {
      systemInstruction: NARRATOR_INSTRUCTION,
      responseMimeType: "application/json",
      responseSchema: NarrativeSchema,
    }
  });

  return parseAIResponse<NarrativeResponse>(response.text);
};

export const initializeGameSession = async (character: CharacterTemplate, setting: string, universeId: string, universeName: string): Promise<SimulationResponse> => {

  // No início, buscamos Lendas Gerais do Universo para dar contexto
  const ragQuery = `Overview history legends of universe ${universeName}`;
  const loreContext = await retrieveContext(ragQuery);

  const formattedLore = loreContext.length > 0 
    ? `[LENDAS E HISTÓRIA DO UNIVERSO (CONTEXTO RAG)]:\n${loreContext.map(m => `- ${m}`).join('\n')}`
    : "";

  const prompt = `
  INICIAR SIMULAÇÃO.

  [CONTAINER / PALCO]:
  Universo: ${universeName} (ID: ${universeId})
  Cenário Inicial da Aventura: ${setting}

  [ALMA / ATOR]:
  Nome: ${character.name}
  Arquétipo: ${character.archetype}
  Backstory/Essência (Imutável): ${character.description}

  ${formattedLore}

  Gere:
  1. Uma DATA e HORA inicial.
  2. A narrativa inicial. Incorpore elementos das [LENDAS] se apropriado, mas foque na materialização do personagem neste cenário.
  3. O estado inicial do mundo.
  4. Os NPCs iniciais.
  `;

  const response = await generateContentWithRetry(NARRATOR_MODEL, {
    contents: prompt,
    config: {
      systemInstruction: NARRATOR_INSTRUCTION + "\nVocê está criando o ESTADO INICIAL de uma nova aventura. Use a Identidade do personagem para moldar como ele percebe o mundo.",
      responseMimeType: "application/json",
      responseSchema: InitSchema,
    }
  }, 6, 3000);

  return parseAIResponse<SimulationResponse>(response.text);
};

import { useState } from 'react';
import { GameState, ChatEntry, PlayerStats, CharacterTemplate } from '../types';
import { initializeGame, generateStory, synchronizeState, summarizeMemory, investigateScene, debugSimulation } from '../services/geminiService';
import { mergeKnowledge } from '../utils/knowledgeUtils';

const MEMORY_THRESHOLD = 8;

const DEFAULT_STATS: PlayerStats = {
  strength: 10,
  agility: 10,
  intelligence: 10,
  spirit: 10,
  health: 100,
  maxHealth: 100
};

// Update signature to accept the evolver function
export const useGameEngine = (evolveUniverse?: (id: string, updates: any) => void) => {
  const [gameState, setGameState] = useState<GameState | null>(null);
  const [isProcessing, setIsProcessing] = useState(false);
  const [isSyncingState, setIsSyncingState] = useState(false);

  const startGame = async (character: CharacterTemplate, setting: string, universeId: string, universeName: string) => {
    setIsProcessing(true);
    try {
      const sim = await initializeGame(character, setting, universeId, universeName);

      const initialEntry: ChatEntry = {
        role: 'model',
        text: sim.narrative,
        simulationData: sim,
        type: 'action'
      };

      const initialKB = mergeKnowledge({
        characters: [],
        locations: [],
        lore: [],
        quests: []
      }, sim.knowledgeUpdate);

      setGameState({
        universeId: universeId,
        player: {
          sourceId: character.id, // THE LINK TO IDENTITY
          name: character.name,
          description: character.description, // Initial state description matches template
          inventory: sim.worldUpdate?.inventoryUpdates?.added || [],
          status: sim.worldUpdate?.playerStatus || "Saudável",
          location: sim.worldUpdate?.newLocation || "Desconhecido",
          stats: { ...DEFAULT_STATS }
        },
        world: {
          time: sim.initialTime || "Início do Ciclo",
          weather: sim.worldUpdate?.currentWeather || "Estável",
          activeEvents: sim.worldUpdate?.worldEvents || [],
          npcs: sim.npcSimulation || []
        },
        knowledgeBase: initialKB,
        summary: "Início da jornada.",
        history: [initialEntry]
      });
    } catch (error) {
      console.error(error);
      alert("Falha na conexão neural.");
    } finally {
      setIsProcessing(false);
    }
  };

  const performAction = async (actionText: string, mode: 'action' | 'investigation' | 'debug') => {
    if (!gameState) return;
    setIsProcessing(true);

    const userEntry: ChatEntry = { role: 'user', text: actionText, type: mode };
    setGameState(prev => prev ? ({ ...prev, history: [...prev.history, userEntry] }) : null);

    try {
      if (mode === 'debug') {
        const result = await debugSimulation(actionText, gameState);
        setGameState(prev => prev ? ({ ...prev, history: [...prev.history, { role: 'system', text: result, type: 'debug' }] }) : null);
        setIsProcessing(false);
      } else if (mode === 'investigation') {
        const result = await investigateScene(actionText, gameState);
        setGameState(prev => prev ? ({ ...prev, history: [...prev.history, { role: 'model', text: result, type: 'investigation' }] }) : null);
        setIsProcessing(false);
      } else {
        const currentState = { ...gameState, history: [...gameState.history, userEntry] };

        if (currentState.history.length > MEMORY_THRESHOLD) {
           summarizeMemory(currentState).then(s => setGameState(prev => prev ? ({...prev, summary: s}) : null));
        }

        const narrativeRes = await generateStory(actionText, currentState);
        const modelEntry: ChatEntry = { role: 'model', text: narrativeRes.narrative, type: 'action' };

        // --- UNIVERSE EVOLUTION CHECK ---
        if (evolveUniverse && ((narrativeRes.canonicalEvents && narrativeRes.canonicalEvents.length > 0) || (narrativeRes.discoveredTruths && narrativeRes.discoveredTruths.length > 0))) {
            console.log("Updating Universe Canon...", narrativeRes.canonicalEvents, narrativeRes.discoveredTruths);
            evolveUniverse(currentState.universeId, {
                newEvents: narrativeRes.canonicalEvents,
                newTruths: narrativeRes.discoveredTruths
            });
        }
        // --------------------------------

        setGameState(prev => {
          if (!prev) return null;
          return {
            ...prev,
            knowledgeBase: mergeKnowledge(prev.knowledgeBase, narrativeRes.knowledgeUpdate),
            history: [...prev.history, modelEntry]
          };
        });

        setIsProcessing(false);
        setIsSyncingState(true);

        try {
            const { world, npcs } = await synchronizeState(actionText, narrativeRes.narrative, currentState, narrativeRes);

            setGameState(prev => {
                if (!prev) return null;

                // Inventory
                let newInv = [...prev.player.inventory];
                if (world.inventoryUpdates?.added) newInv.push(...world.inventoryUpdates.added);
                if (world.inventoryUpdates?.removed) newInv = newInv.filter(i => !world.inventoryUpdates.removed?.includes(i));

                // Stats Update
                const newStats = { ...prev.player.stats };
                if (world.statChanges) {
                  Object.entries(world.statChanges).forEach(([key, val]) => {
                    const k = key as keyof PlayerStats;
                    if (typeof val === 'number') {
                      newStats[k] = Math.max(0, Math.min(newStats[k] + val, k === 'health' ? newStats.maxHealth : 99));
                    }
                  });
                }

                return {
                    ...prev,
                    player: { ...prev.player, status: world.playerStatus, location: world.newLocation, inventory: newInv, stats: newStats },
                    world: { ...prev.world, time: calculateNewTime(prev.world.time, world.timePassed), weather: world.currentWeather, activeEvents: world.worldEvents, npcs: npcs.npcs || prev.world.npcs }
                };
            });
        } finally {
            setIsSyncingState(false);
        }
      }
    } catch (error) {
      console.error(error);
      setIsProcessing(false);
    }
  };

  const resetGame = () => { if (confirm("Sair da simulação atual? O progresso não salvo será perdido, mas o Universo manterá as memórias.")) { setGameState(null); } };
  const restoreGame = (s: GameState) => setGameState(s);

  return { gameState, isProcessing, isSyncingState, startGame, performAction, resetGame, restoreGame };
};

function calculateNewTime(currentTime: string, timePassed: string): string {
    if (!currentTime || !timePassed) return currentTime;
    let minutesToAdd = 0;
    const match = timePassed.match(/(\d+)\s*(min|h|d)/i);
    if (match) {
        const val = parseInt(match[1]);
        const unit = match[2].toLowerCase();
        minutesToAdd = unit.startsWith('h') ? val * 60 : unit.startsWith('d') ? val * 1440 : val;
    }
    if (currentTime.includes("Ciclo") || currentTime.includes("Era")) return currentTime; 

    try {
        const [dPart, tPart] = currentTime.split(' ');
        if (!dPart || !tPart) return currentTime;
        const [d, m, y] = dPart.split('/').map(Number);
        const [h, min] = tPart.split(':').map(Number);
        const date = new Date(y, m - 1, d, h, min + minutesToAdd);
        const pad = (n: number) => n.toString().padStart(2, '0');
        return `${pad(date.getDate())}/${pad(date.getMonth() + 1)}/${date.getFullYear()} ${pad(date.getHours())}:${pad(date.getMinutes())}`;
    } catch(e) {
        return currentTime;
    }
}

import React, { useState, useEffect } from 'react';
import ApiKeyModal from './components/ApiKeyModal';
import WorldStatePanel from './components/WorldStatePanel';
import GameHeader from './components/GameHeader';
import GameLog from './components/GameLog';
import InputArea from './components/InputArea';
// EntryScreen import removed

// Navigation & Creators
import BottomNav, { NavTab } from './components/BottomNav';
import { UniverseList, CharacterList } from './components/library/LibraryViews';
import UniverseCreator from './components/creators/UniverseCreator';
import CharacterCreator from './components/creators/CharacterCreator';
import AdventureLauncher from './components/creators/AdventureLauncher';

import { useGameEngine } from './hooks/useGameEngine';
import { usePersistence } from './hooks/usePersistence';
import { useLibrary } from './hooks/useLibrary';
import { UniverseTemplate, CharacterTemplate } from './types';
import { checkBackendHealth } from './services/ragService';

// Types for Navigation
type ViewState = 'ADVENTURE_LAUNCHER' | 'UNIVERSE_LIST' | 'UNIVERSE_CREATOR' | 'CHARACTER_LIST' | 'CHARACTER_CREATOR' | 'SETTINGS' | 'GAME';

function App() {
  const [hasApiKey, setHasApiKey] = useState(false);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isInvestigationMode, setIsInvestigationMode] = useState(false);

  // Navigation State
  const [currentView, setCurrentView] = useState<ViewState>('ADVENTURE_LAUNCHER');

  // Settings State
  const [backendStatus, setBackendStatus] = useState<'checking' | 'online' | 'offline'>('checking');

  // Library Hook (Now provides evolveUniverse & trackCharacterUsage)
  const { universes, characters, addUniverse, addCharacter, restoreDefaults, evolveUniverse, trackCharacterUsage } = useLibrary();

  // Hooks (Pass evolveUniverse to engine)
  const { gameState, isProcessing, startGame, performAction, resetGame, restoreGame } = useGameEngine(evolveUniverse);
  const { saveGame, parseSaveFile } = usePersistence();

  // Auto-open sidebar when game starts
  useEffect(() => {
    if (gameState && currentView === 'GAME') {
      setIsSidebarOpen(true);
    }
  }, [gameState, currentView]);

  // Check Backend Health when entering Settings
  useEffect(() => {
    if (currentView === 'SETTINGS') {
      setBackendStatus('checking');
      checkBackendHealth().then(isOnline => {
        setBackendStatus(isOnline ? 'online' : 'offline');
      });
    }
  }, [currentView]);

  const handleStartAdventure = (u: UniverseTemplate, c: CharacterTemplate, planetLocation: string) => {

    // 1. Update Character Usage Stats
    trackCharacterUsage(c.id);

    // 2. Check if this is a NEW world for this universe and register it
    const isNewWorld = !u.worlds?.some(w => w.name.toLowerCase() === planetLocation.toLowerCase());
    if (isNewWorld) {
        evolveUniverse(u.id, {
            newWorld: { 
                name: planetLocation, 
                description: "Mundo descoberto recentemente." 
            }
        });
    }

    // We construct a DEEP context including physics, laws, history AND persistent legends
    const physicsBlock = u.physics && u.physics.length > 0 ? `LEIS DA REALIDADE (Imutáveis):\n${u.physics.map(p=>`- ${p}`).join('\n')}` : '';
    const truthsBlock = u.knownTruths && u.knownTruths.length > 0 ? `VERDADES DESCOBERTAS (Conhecimento Acumulado):\n${u.knownTruths.map(t=>`- ${t}`).join('\n')}` : '';

    const timelineBlock = u.chronicles && u.chronicles.length > 0 ? `CRONOLOGIA CANÔNICA DO UNIVERSO (HISTÓRICO COMPARTILHADO):\n${u.chronicles.map(t=>`[${t.year}] ${t.event}`).join('\n')}` : '';

    const legendsBlock = u.champions && u.champions.length > 0 ? `LENDAS E HERÓIS PASSADOS:\n${u.champions.map(ch => `- ${ch.characterName}: ${ch.feat} (${ch.status})`).join('\n')}` : '';

    const magicBlock = u.magicSystem ? `SISTEMA DE MAGIA/TECNOLOGIA: ${u.magicSystem}` : '';

    const fullSettingContext = `
      UNIVERSE CONTAINER: ${u.name} (${u.genre})
      DESCRIÇÃO DO UNIVERSO: ${u.description}
      COSMOLOGIA: ${u.cosmology || 'Desconhecida'}

      ${physicsBlock}

      ${magicBlock}

      ${truthsBlock}

      ${timelineBlock}

      ${legendsBlock}

      ---
      STARTING WORLD / LOCAL DA TRAMA: ${planetLocation}
      ---
    `;

    // Updated signature: pass full Character Object and Universe info
    startGame(c, fullSettingContext, u.id, u.name);
    setCurrentView('GAME');
  };

  const handleLoadGame = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    try {
      const loadedState = await parseSaveFile(file);
      restoreGame(loadedState);
      setCurrentView('GAME');
    } catch (err) {
      console.error(err);
      alert("Arquivo de save inválido ou corrompido.");
    }
  };

  const handleExitToHub = () => {
    if (window.confirm("Sair para o Menu Principal? O progresso não salvo será perdido.")) {
      resetGame(); // Clears current session
      setCurrentView('ADVENTURE_LAUNCHER');
    }
  };

  // Determine active tab for BottomNav based on currentView
  const getActiveTab = (): NavTab => {
    if (currentView === 'UNIVERSE_LIST' || currentView === 'UNIVERSE_CREATOR') return 'UNIVERSES';
    if (currentView === 'CHARACTER_LIST' || currentView === 'CHARACTER_CREATOR') return 'CHARACTERS';
    if (currentView === 'SETTINGS') return 'SETTINGS';
    return 'PLAY';
  };

  const handleTabChange = (tab: NavTab) => {
    switch (tab) {
      case 'PLAY': setCurrentView('ADVENTURE_LAUNCHER'); break;
      case 'UNIVERSES': setCurrentView('UNIVERSE_LIST'); break;
      case 'CHARACTERS': setCurrentView('CHARACTER_LIST'); break;
      case 'SETTINGS': setCurrentView('SETTINGS'); break;
    }
  };

  // --- RENDER LOGIC ---

  if (!hasApiKey) return <ApiKeyModal onKeySelected={() => setHasApiKey(true)} />;

  return (
    <div className="flex h-screen bg-stone-950 text-stone-200 overflow-hidden relative">

      {/* Main Content Area */}
      <div className={`flex-1 flex flex-col min-w-0 relative transition-all duration-300 ${isSidebarOpen && currentView === 'GAME' ? 'mr-0 md:mr-80' : 'mr-0'}`}>

        {/* Header is always visible but changes context */}
        <GameHeader 
          gameState={gameState}
          setupMode={currentView !== 'GAME'}
          isSidebarOpen={isSidebarOpen}
          onToggleSidebar={() => setIsSidebarOpen(!isSidebarOpen)}
          onReset={handleExitToHub} // In Game Mode, this exits to Hub
          onSave={() => saveGame(gameState)}
          onLoad={handleLoadGame}
        />

        {/* View Router */}

        {/* TAB: PLAY */}
        {currentView === 'ADVENTURE_LAUNCHER' && (
          <AdventureLauncher 
            universes={universes}
            characters={characters}
            onStartAdventure={handleStartAdventure}
            onCancel={() => {}} // No cancel action needed on root
          />
        )}

        {/* TAB: UNIVERSES */}
        {currentView === 'UNIVERSE_LIST' && (
          <UniverseList onCreate={() => setCurrentView('UNIVERSE_CREATOR')} />
        )}
        {currentView === 'UNIVERSE_CREATOR' && (
          <UniverseCreator 
            onSave={(t) => { addUniverse(t); setCurrentView('UNIVERSE_LIST'); }} 
            onCancel={() => setCurrentView('UNIVERSE_LIST')} 
          />
        )}

        {/* TAB: CHARACTERS */}
        {currentView === 'CHARACTER_LIST' && (
          <CharacterList onCreate={() => setCurrentView('CHARACTER_CREATOR')} />
        )}
        {currentView === 'CHARACTER_CREATOR' && (
          <CharacterCreator 
            onSave={(t) => { addCharacter(t); setCurrentView('CHARACTER_LIST'); }} 
            onCancel={() => setCurrentView('CHARACTER_LIST')} 
          />
        )}

        {/* TAB: SETTINGS */}
        {currentView === 'SETTINGS' && (
           <div className="flex-1 flex flex-col items-center justify-center text-stone-500 text-sm p-8 animate-fade-in overflow-y-auto">
              <div className="text-center space-y-4 max-w-md w-full pb-20">
                 <h2 className="text-2xl font-serif text-stone-300">Sistema Cronos</h2>
                 <p className="text-xs uppercase tracking-widest border-b border-stone-900 pb-4">Diagnósticos & Configuração</p>

                 <div className="bg-stone-900/30 p-6 rounded border border-stone-800 text-left space-y-6">

                   <div className="border-b border-stone-800 pb-2 mb-2 flex justify-between items-center">
                      <h3 className="text-stone-400 font-serif text-sm uppercase tracking-wider">Topologia de Rede</h3>
                      <span className="text-[9px] text-stone-600 bg-stone-900 px-2 py-0.5 rounded">2 Nós Ativos</span>
                   </div>

                   {/* Google API Status */}
                   <div>
                     <label className="block text-[10px] uppercase text-stone-500 mb-1 flex items-center justify-between">
                        <span>Núcleo Neural (LLM)</span>
                        <span className="text-stone-600">Google Cloud</span>
                     </label>
                     <div className="flex items-center gap-2 text-green-500 text-xs font-mono bg-stone-950/50 p-2 rounded border border-stone-900">
                       <span className="w-2 h-2 bg-green-500 rounded-full animate-pulse"></span>
                       Gemini 2.5 API (Conectado)
                     </div>
                   </div>

                   {/* Backend/RAG Status */}
                   <div>
                     <label className="block text-[10px] uppercase text-stone-500 mb-1 flex items-center justify-between">
                        <span>Orquestrador de Memória</span>
                        <span className="text-stone-600">Servidor RAG (Python)</span>
                     </label>
                     <div className={`flex items-center gap-2 text-xs font-mono bg-stone-950/50 p-2 rounded border border-stone-900 transition-colors duration-300 ${
                       backendStatus === 'online' ? 'text-green-500 border-green-900/30' : backendStatus === 'checking' ? 'text-amber-500' : 'text-red-500 border-red-900/30'
                     }`}>
                       <span className={`w-2 h-2 rounded-full ${
                         backendStatus === 'online' ? 'bg-green-500 animate-pulse' : backendStatus === 'checking' ? 'bg-amber-500 animate-bounce' : 'bg-red-500'
                       }`}></span>
                       {backendStatus === 'checking' ? 'Negociando handshake...' : backendStatus === 'online' ? 'Link Neural Estável' : 'Sinal Perdido (Offline)'}
                     </div>

                     {/* Sub-systems visualization */}
                     <div className="mt-2 pl-3 border-l-2 border-stone-800 space-y-1">
                        <div className="flex items-center justify-between text-[10px] py-1">
                           <span className="text-stone-400">Vector Store (ChromaDB)</span>
                           <span className={backendStatus === 'online' ? "text-green-600" : "text-stone-700"}>{backendStatus === 'online' ? '●' : '○'}</span>
                        </div>
                        <div className="flex items-center justify-between text-[10px] py-1">
                           <span className="text-stone-400">Knowledge Graph (Neo4j)</span>
                           <span className={backendStatus === 'online' ? "text-green-600" : "text-stone-700"}>{backendStatus === 'online' ? '●' : '○'}</span>
                        </div>
                        <div className="flex items-center justify-between text-[10px] py-1">
                           <span className="text-stone-400">Event Logs (SQLite)</span>
                           <span className={backendStatus === 'online' ? "text-green-600" : "text-stone-700"}>{backendStatus === 'online' ? '●' : '○'}</span>
                        </div>
                     </div>

                     {backendStatus === 'offline' && (
                       <p className="text-[10px] text-red-900/70 mt-2 italic border-t border-red-900/10 pt-1">
                         A persistência de longo prazo está indisponível. A simulação usará apenas a memória de contexto (RAM).
                       </p>
                     )}
                   </div>

                   <div className="h-px bg-stone-800 w-full my-4"></div>

                   <div>
                     <label className="block text-[10px] uppercase text-stone-600 mb-1">Versão do Cliente</label>
                     <span className="text-stone-400 text-xs font-mono">v1.3.0 (Universe Deep Layer)</span>
                   </div>

                    <div>
                     <label className="block text-[10px] uppercase text-stone-600 mb-1">Manutenção</label>
                     <div className="flex flex-col gap-2">
                        <button onClick={() => { if(confirm('Restaurar universos e personagens de exemplo?')) { restoreDefaults(); alert('Templates restaurados!'); window.location.reload(); } }} className="text-amber-500 hover:text-amber-400 text-xs text-left">
                          Restaurar Templates de Exemplo
                        </button>
                        <button onClick={() => { if(confirm('Limpar todas as bibliotecas e resetar o app?')) { localStorage.clear(); window.location.reload(); } }} className="text-red-500 hover:text-red-400 text-xs text-left">
                          Limpar Dados Locais (Reset Fábrica)
                        </button>
                     </div>
                   </div>
                 </div>
              </div>
           </div>
        )}

        {/* GAME VIEW */}
        {currentView === 'GAME' && (
          <>
            <GameLog 
              history={gameState?.history || []} 
              isProcessing={isProcessing} 
              isInvestigationMode={isInvestigationMode}
            />
            <InputArea 
              onSend={performAction}
              isProcessing={isProcessing}
              isInvestigationMode={isInvestigationMode}
              onToggleMode={() => setIsInvestigationMode(!isInvestigationMode)}
            />
          </>
        )}
      </div>

      {/* Sidebar - Only active in GAME view */}
      {currentView === 'GAME' && (
        <WorldStatePanel 
          gameState={gameState} 
          isOpen={isSidebarOpen} 
          onToggle={() => setIsSidebarOpen(!isSidebarOpen)} 
        />
      )}

      {/* Bottom Navigation - Only active when NOT in game */}
      {currentView !== 'GAME' && (
        <BottomNav activeTab={getActiveTab()} onTabChange={handleTabChange} />
      )}

    </div>
  );
}

export default App;
